public int countTriple(String str) {
    int count = 0;
    for (int i = 0; i < str.length() - 2; i++) {
        if (str.charAt(i) == str.charAt(i+1) && str.charAt(i) == str.charAt(i+2)) {
            count++;
        }
    }
    return count;
}

public int[] seriesUp(int n) {
    int[] result = new int[n * (n + 1) / 2];
    int index = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            result[index++] = j;
        }
    }
    return result;
}
